args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-29-remaining-maps/transport');S<-file.path(P,'biofigure')
suppressPackageStartupMessages({library(ggplot2);library(sf);library(grid);library(ggspatial)})
z<-read.csv(file.path(W,'v11_kcdc_province_cases.csv'));g<-st_read(file.path(W,'gadm41_KOR.gpkg'),layer='ADM_ADM_1',quiet=TRUE)
stopifnot(nrow(g)==17,nrow(z)==17,setequal(z$gadm_name,g$NAME_1));g<-g[match(z$gadm_name,g$NAME_1),];stopifnot(identical(g$NAME_1,z$gadm_name));g$cumulative_cases<-z$cumulative_cases
# Display-only simplification in metres; no value interpolation or geometry tracing.
g<-st_transform(st_simplify(st_transform(st_make_valid(g),5179),dTolerance=100,preserveTopology=TRUE),4326)
gp<-file.path(P,'results/plot_data/asf11_kcdc_provinces_gadm41_20261029.gpkg');if(file.exists(gp))unlink(gp);st_write(g,gp,layer='province_cases',quiet=TRUE)
