outer<-data.frame(gadm_name=c('Seoul','Incheon','Sejong','Daejeon','Gwangju','Daegu','Ulsan','Busan'),x=c(124.6,124.6,124.6,124.6,124.6,131.15,131.15,131.15),y=c(38.05,37.5,36.9,36.15,35.25,36.05,35.5,34.85),px=c(126.98,126.62,127.25,127.4,126.85,128.6,129.25,129.05),py=c(37.56,37.45,36.5,36.33,35.15,35.87,35.5,35.15),side=c(rep('left',5),rep('right',3)))
outer$cumulative_cases<-z$cumulative_cases[match(outer$gadm_name,z$gadm_name)];outer$label<-paste0(outer$gadm_name,', ',format(outer$cumulative_cases,big.mark=',',trim=TRUE));outer$line_x<-ifelse(outer$side=='left',outer$x+.1,outer$x-.1);outer$hjust<-ifelse(outer$side=='left',0,1)
write.csv(rbind(data.frame(inner[,c('gadm_name','x','y','label')],position='interior'),data.frame(outer[,c('gadm_name','x','y','label')],position='callout')),file.path(P,'results/plot_data/asf11_kcdc_map_labels_20261029.csv'),row.names=FALSE)
p<-ggplot()+geom_sf(data=g,aes(fill=cumulative_cases),colour='white',linewidth=.22)+scale_fill_gradient(low='#FFDDDD',high='#D52332',limits=c(0,7200),breaks=c(0,2000,4000,6000),labels=scales::comma,name='Cumulative confirmed cases',guide=guide_colourbar(direction='horizontal',title.position='top',barwidth=unit(65,'mm'),barheight=unit(3,'mm'),ticks.colour='#30343B'))+
 geom_segment(data=outer,aes(x=px,y=py,xend=line_x,yend=y),linewidth=.22,colour='#3E464C')+
 geom_point(data=outer,aes(px,py),size=.8,colour='#30343B')+
 geom_label(data=inner,aes(x,y,label=label),family='Arial',size=2.46,lineheight=1.0,colour='#17232A',fill='white',linewidth=0,label.padding=unit(.15,'mm'))+
 geom_label(data=outer,aes(x,y,label=label,hjust=hjust),family='Arial',size=2.46,vjust=-.3,colour='#17232A',fill='white',linewidth=0,label.padding=unit(.1,'mm'))+
 annotate('segment',x=131.2,xend=131.2,y=38.1,yend=38.55,linewidth=.45,arrow=arrow(type='closed',length=unit(2,'mm')))+annotate('text',x=131.2,y=38.7,label='N',family='Arial',size=2.46)+
 coord_sf(xlim=c(124.4,131.5),ylim=c(32.65,38.9),crs=4326,datum=NA,expand=FALSE,clip='off')+
 annotation_scale(location='bl',width_hint=.28,text_family='Arial',text_cex=.6,line_width=.4,height=unit(1.5,'mm'),pad_x=unit(5,'mm'),pad_y=unit(3,'mm'))+
 theme_void(base_family='Arial',base_size=7)+theme(legend.position='bottom',legend.text=element_text(size=7),legend.title=element_text(size=7),legend.margin=margin(0,0,0,0),plot.margin=margin(2,2,2,2))
saveRDS(p,file.path(W,'plot.rds'));ggsave(file.path(W,'exploratory.png'),p,width=136,height=145,units='mm',dpi=180,device=ragg::agg_png,bg='white')
ragg::agg_png(file.path(W,'grob-measurement.png'),width=136,height=145,units='mm',res=180,background='white');gg<-ggplotGrob(p);labels<-character();sizes<-numeric();fix<-function(x){if(inherits(x,'text')){x$gp$fontfamily<-'Arial';if(!is.null(x$gp$fontsize)){x$gp$fontsize<-pmax(7,x$gp$fontsize);sizes<<-c(sizes,x$gp$fontsize)};labels<<-c(labels,as.character(x$label))};if(length(x$grobs))x$grobs<-lapply(x$grobs,fix);if(length(x$children))x$children<-do.call(gList,lapply(x$children,fix));x};gg<-fix(gg);dev.off();saveRDS(gg,file.path(W,'composed-vector-grob.rds'));saveRDS(ggplotify::as.ggplot(gg)+theme(text=element_text(family='Arial',size=7),plot.margin=margin(0,0,0,0)),file.path(W,'render-object.rds'))
jsonlite::write_json(list(labels=unique(c(labels,'100 km')),point_sizes=sort(unique(sizes))),file.path(W,'text-manifest.json'),auto_unbox=TRUE,pretty=TRUE)
jsonlite::write_json(list(stem='asf11_kcdc_korea_cases_fig1b_20261029',width_mm=136,height_mm=145,regions=17,geometry_crs='EPSG:4326; GADM4.1 boundaries projected EPSG:5179 for100m simplification and back',count_closure=TRUE,data_origin='Exact KCDC2020-09-30 regional cumulative confirmed cases from official press release page2; all17 values match Ren2022Fig1B. Border screening1511 excluded from province map;22301 regional+1511 border=23812 national. GADM4.1 boundaries are a documented display-geometry adaptation;100m topology-preserving simplification. Figure1B only; timeline and five time-series panels not reproduced.',palette='Source-aligned pink to red continuous raw cumulative-case count scale; no normalization per population'),file.path(W,'input-qc.json'),auto_unbox=TRUE,pretty=TRUE)
